export function isDirectedAcyclicGraph(graph) {
  const inDegrees = graph.getInDegrees();
  const queue = [];

  for (const [node, degree] of inDegrees.entries()) {
    if (degree === 0) {
      queue.push(node);
    }
  }

  let visited = 0;

  for (let index = 0; index < queue.length; index += 1) {
    const node = queue[index];
    visited += 1;

    for (const neighbor of graph.getNeighbors(node)) {
      const nextDegree = inDegrees.get(neighbor) - 1;
      inDegrees.set(neighbor, nextDegree);

      if (nextDegree === 0) {
        queue.push(neighbor);
      }
    }
  }

  return visited === graph.nodeCount;
}

