import { isPythonIntLiteral, parsePythonIntLiteral } from "./integer.mjs";

const OPTIONS = [
  { key: "a", flag: "--a", metavar: "A" },
  { key: "b", flag: "--b", metavar: "B" },
  { key: "c", flag: "--c", metavar: "C" },
  { key: "d", flag: "--d", metavar: "D" },
  { key: "e", flag: "--e", metavar: "E" },
];

const OPTION_BY_FLAG = new Map(OPTIONS.map((option) => [option.flag, option]));

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return "test5.mjs";
  }

  const parts = scriptPath.split(/[\\/]/);
  return parts[parts.length - 1] || "test5.mjs";
}

export function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E\n`;
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n  --d D\n  --e E\n`;
}

function buildExpectedOneArgumentError(flag) {
  return `argument ${flag}: expected one argument`;
}

function buildInvalidIntError(flag, value) {
  return `argument ${flag}: invalid int value: '${value}'`;
}

function buildMissingRequiredError(flags) {
  return `the following arguments are required: ${flags.join(", ")}`;
}

function buildUnrecognizedArgumentsError(tokens) {
  return `unrecognized arguments: ${tokens.join(" ")}`;
}

export function parseTest5Args(argv, programName = "test5.mjs") {
  const values = Object.create(null);
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      return {
        kind: "help",
        helpText: buildHelp(programName),
      };
    }

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const option = OPTION_BY_FLAG.get(flag);

      if (!option) {
        extras.push(token);
        continue;
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        const next = argv[index + 1];

        if (next === undefined || (next.startsWith("-") && !isPythonIntLiteral(next))) {
          return {
            kind: "error",
            code: 2,
            usageText: buildUsage(programName),
            message: buildExpectedOneArgumentError(flag),
          };
        }

        rawValue = next;
        index += 1;
      }

      const parsedValue = parsePythonIntLiteral(rawValue);

      if (parsedValue === null) {
        return {
          kind: "error",
          code: 2,
          usageText: buildUsage(programName),
          message: buildInvalidIntError(flag, rawValue),
        };
      }

      values[option.key] = parsedValue;
      continue;
    }

    extras.push(token);
  }

  const missing = OPTIONS
    .filter((option) => values[option.key] === undefined)
    .map((option) => option.flag);

  if (missing.length > 0) {
    return {
      kind: "error",
      code: 2,
      usageText: buildUsage(programName),
      message: buildMissingRequiredError(missing),
    };
  }

  if (extras.length > 0) {
    return {
      kind: "error",
      code: 2,
      usageText: buildUsage(programName),
      message: buildUnrecognizedArgumentsError(extras),
    };
  }

  return {
    kind: "success",
    values,
  };
}

