import { getProgramName, parseTest5Args } from "./cli/test5-args.mjs";
import { isDirectedAcyclicGraph } from "./graph/dag.mjs";
import { DiGraph } from "./graph/digraph.mjs";

export { getProgramName };

export function runTest5(argv, io = {}) {
  const programName = io.programName ?? "test5.mjs";
  const stdout = io.stdout ?? process.stdout;
  const stderr = io.stderr ?? process.stderr;
  const parsed = parseTest5Args(argv, programName);

  if (parsed.kind === "help") {
    stdout.write(parsed.helpText);
    return 0;
  }

  if (parsed.kind === "error") {
    stderr.write(parsed.usageText);
    stderr.write(`${programName}: error: ${parsed.message}\n`);
    return parsed.code;
  }

  const { a, b, c, d, e } = parsed.values;
  const graph = new DiGraph();
  graph.addEdgesFrom([
    [a, b],
    [b, c],
    [c, d],
    [d, e],
  ]);

  stdout.write(`${isDirectedAcyclicGraph(graph) ? "True" : "False"}\n`);
  return 0;
}

