export class DiGraph {
  constructor() {
    this.adjacency = new Map();
    this.inDegrees = new Map();
  }

  ensureNode(node) {
    if (!this.adjacency.has(node)) {
      this.adjacency.set(node, new Set());
    }

    if (!this.inDegrees.has(node)) {
      this.inDegrees.set(node, 0);
    }
  }

  addEdge(from, to) {
    this.ensureNode(from);
    this.ensureNode(to);

    const neighbors = this.adjacency.get(from);

    if (neighbors.has(to)) {
      return;
    }

    neighbors.add(to);
    this.inDegrees.set(to, this.inDegrees.get(to) + 1);
  }

  addEdgesFrom(edges) {
    for (const [from, to] of edges) {
      this.addEdge(from, to);
    }
  }

  getNeighbors(node) {
    return this.adjacency.get(node) ?? new Set();
  }

  getInDegrees() {
    return new Map(this.inDegrees);
  }

  get nodeCount() {
    return this.adjacency.size;
  }
}

